import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi, beforeEach } from "vitest";
import { DeleteAccountSection } from "./DeleteAccountSection";

const mockRefresh = vi.fn();
const mockGetUser = vi.fn();
const mockInsert = vi.fn();
const mockUpdateEq = vi.fn();
let mockInsertError: { message: string } | null = null;
let mockUpdateError: { message: string } | null = null;
let mockUpdateData: { id: string }[] = [{ id: "req-456" }];

vi.mock("next/navigation", () => ({
  useRouter: () => ({ refresh: mockRefresh }),
}));

vi.mock("@/lib/supabase/client", () => ({
  createClient: () => ({
    auth: { getUser: mockGetUser },
    from: () => ({
      insert: (data: unknown) => {
        mockInsert(data);
        return Promise.resolve({ error: mockInsertError });
      },
      update: (data: unknown) => ({
        eq: (field: string, value: string) => {
          mockUpdateEq(data, field, value);
          return {
            select: () => Promise.resolve({ data: mockUpdateData, error: mockUpdateError }),
          };
        },
      }),
    }),
  }),
}));

function resetFixtures() {
  vi.resetAllMocks();
  mockInsertError = null;
  mockUpdateError = null;
  mockUpdateData = [{ id: "req-456" }];
}

describe("DeleteAccountSection — no pending request", () => {
  beforeEach(() => {
    resetFixtures();
    mockGetUser.mockResolvedValue({ data: { user: { id: "user-123" } } });
  });

  it("renders the danger zone card", () => {
    render(<DeleteAccountSection existingRequest={null} />);
    expect(screen.getByText("Danger zone")).toBeInTheDocument();
    expect(screen.getByText("Delete account")).toBeInTheDocument();
  });

  it("opens confirmation dialog on click", async () => {
    render(<DeleteAccountSection existingRequest={null} />);
    await userEvent.click(screen.getByText("Delete account"));
    expect(screen.getByText("Delete your account?")).toBeInTheDocument();
    expect(screen.getByText(/scheduled for deletion in 30 days/)).toBeInTheDocument();
  });

  it("closes dialog on Cancel", async () => {
    render(<DeleteAccountSection existingRequest={null} />);
    await userEvent.click(screen.getByText("Delete account"));
    await userEvent.click(screen.getByRole("button", { name: "Cancel" }));
    expect(screen.queryByText("Delete your account?")).not.toBeInTheDocument();
  });

  it("closes dialog on Escape", async () => {
    render(<DeleteAccountSection existingRequest={null} />);
    await userEvent.click(screen.getByText("Delete account"));
    await userEvent.keyboard("{Escape}");
    expect(screen.queryByText("Delete your account?")).not.toBeInTheDocument();
  });

  it("inserts deletion request on confirm", async () => {
    render(<DeleteAccountSection existingRequest={null} />);
    await userEvent.click(screen.getByText("Delete account"));
    await userEvent.click(screen.getByText("Delete my account"));
    await waitFor(() => {
      expect(mockInsert).toHaveBeenCalledWith(
        expect.objectContaining({
          user_id: "user-123",
          scheduled_for: expect.any(String),
        }),
      );
    });
  });

  it("calls router.refresh after deletion request", async () => {
    render(<DeleteAccountSection existingRequest={null} />);
    await userEvent.click(screen.getByText("Delete account"));
    await userEvent.click(screen.getByText("Delete my account"));
    await waitFor(() => {
      expect(mockRefresh).toHaveBeenCalled();
    });
  });

  it("shows error when deletion insert fails", async () => {
    mockInsertError = { message: "Failed" };
    render(<DeleteAccountSection existingRequest={null} />);
    await userEvent.click(screen.getByText("Delete account"));
    await userEvent.click(screen.getByText("Delete my account"));
    await waitFor(() => {
      expect(
        screen.getByText("Failed to request account deletion. Please try again."),
      ).toBeInTheDocument();
    });
  });
});

describe("DeleteAccountSection — pending request", () => {
  const pendingRequest = {
    id: "req-456",
    scheduledFor: "2026-05-24T00:00:00.000Z",
    status: "pending",
  };

  beforeEach(() => {
    resetFixtures();
  });

  it("shows pending deletion info", () => {
    render(<DeleteAccountSection existingRequest={pendingRequest} />);
    expect(screen.getByText("Account deletion pending")).toBeInTheDocument();
    expect(screen.getByText(/May 24, 2026/)).toBeInTheDocument();
  });

  it("shows cancel deletion button", () => {
    render(<DeleteAccountSection existingRequest={pendingRequest} />);
    expect(screen.getByRole("button", { name: "Cancel deletion" })).toBeInTheDocument();
  });

  it("cancels deletion request on click", async () => {
    render(<DeleteAccountSection existingRequest={pendingRequest} />);
    await userEvent.click(screen.getByRole("button", { name: "Cancel deletion" }));
    await waitFor(() => {
      expect(mockUpdateEq).toHaveBeenCalledWith({ status: "cancelled" }, "id", "req-456");
    });
  });

  it("calls router.refresh after cancellation", async () => {
    render(<DeleteAccountSection existingRequest={pendingRequest} />);
    await userEvent.click(screen.getByRole("button", { name: "Cancel deletion" }));
    await waitFor(() => {
      expect(mockRefresh).toHaveBeenCalled();
    });
  });

  it("shows error when cancellation fails", async () => {
    mockUpdateError = { message: "Failed" };
    render(<DeleteAccountSection existingRequest={pendingRequest} />);
    await userEvent.click(screen.getByRole("button", { name: "Cancel deletion" }));
    await waitFor(() => {
      expect(screen.getByText("Failed to cancel deletion. Please try again.")).toBeInTheDocument();
    });
  });

  it("shows error when update affects zero rows (RLS silent fail)", async () => {
    mockUpdateData = [];
    render(<DeleteAccountSection existingRequest={pendingRequest} />);
    await userEvent.click(screen.getByRole("button", { name: "Cancel deletion" }));
    await waitFor(() => {
      expect(screen.getByText("Failed to cancel deletion. Please try again.")).toBeInTheDocument();
    });
    expect(mockRefresh).not.toHaveBeenCalled();
  });
});

