"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import { createClient } from "@/lib/supabase/client";
import { Button } from "@/components/ui/Button";
import { GlassCard } from "@/components/ui/GlassCard";

interface DeletionRequest {
  id: string;
  scheduledFor: string;
  status: string;
}

function ConfirmationDialog({
  onConfirm,
  onCancel,
}: {
  onConfirm: () => void;
  onCancel: () => void;
}) {
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") onCancel();
    },
    [onCancel],
  );

  useEffect(() => {
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="delete-dialog-title"
    >
      <GlassCard className="mx-4 max-w-md p-8">
        <h3 id="delete-dialog-title" className="font-serif text-xl font-bold text-white">
          Delete your account?
        </h3>
        <p className="mt-3 text-sm text-smc-text-muted leading-relaxed">
          Your account will be scheduled for deletion in 30 days. You can cancel anytime before
          then. After 30 days, all your data will be permanently removed.
        </p>
        <div className="mt-6 flex gap-3">
          <Button variant="ghost" fullWidth={false} onClick={onCancel}>
            Cancel
          </Button>
          <button
            onClick={onConfirm}
            className="rounded-[20px] bg-smc-danger px-5 py-3 text-sm font-medium text-white transition-opacity hover:opacity-90"
          >
            Delete my account
          </button>
        </div>
      </GlassCard>
    </div>
  );
}

export function DeleteAccountSection({
  existingRequest,
}: {
  existingRequest: DeletionRequest | null;
}) {
  const router = useRouter();
  const [showDialog, setShowDialog] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleDelete() {
    setLoading(true);
    setError(null);

    const supabase = createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return;

    const scheduledFor = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

    const { error: insertError } = await supabase.from("account_deletion_requests").insert({
      user_id: user.id,
      scheduled_for: scheduledFor,
    });

    setLoading(false);
    setShowDialog(false);

    if (insertError) {
      setError("Failed to request account deletion. Please try again.");
      return;
    }

    router.refresh();
  }

  async function handleCancelDeletion() {
    if (!existingRequest) return;

    setLoading(true);
    setError(null);

    const supabase = createClient();
    const { data, error: updateError } = await supabase
      .from("account_deletion_requests")
      .update({ status: "cancelled" })
      .eq("id", existingRequest.id)
      .select("id");

    setLoading(false);

    if (updateError || !data || data.length === 0) {
      setError("Failed to cancel deletion. Please try again.");
      return;
    }

    router.refresh();
  }

  return (
    <div className="mt-8">
      {existingRequest ? (
        <GlassCard className="border-smc-danger/30">
          <h2 className="font-serif text-xl font-bold text-smc-danger">Account deletion pending</h2>
          <p className="mt-2 text-sm text-smc-text-muted">
            Your account is scheduled for deletion on{" "}
            <span className="text-white">
              {new Date(existingRequest.scheduledFor).toLocaleDateString("en-US", {
                month: "long",
                day: "numeric",
                year: "numeric",
              })}
            </span>
            . You can cancel before this date to keep your account.
          </p>
          <div className="mt-4">
            <Button
              variant="ghost"
              fullWidth={false}
              onClick={handleCancelDeletion}
              disabled={loading}
            >
              {loading ? "Cancelling..." : "Cancel deletion"}
            </Button>
          </div>
        </GlassCard>
      ) : (
        <GlassCard>
          <h2 className="font-serif text-xl font-bold text-white">Danger zone</h2>
          <p className="mt-2 text-sm text-smc-text-muted">
            Permanently delete your account and all associated data.
          </p>
          <div className="mt-4">
            <button
              onClick={() => setShowDialog(true)}
              className="rounded-[20px] border border-smc-danger/30 bg-transparent px-5 py-3 text-sm font-medium text-smc-danger transition-colors hover:bg-smc-danger/10"
            >
              Delete account
            </button>
          </div>
        </GlassCard>
      )}

      {error && <p className="mt-3 text-sm text-smc-danger">{error}</p>}

      {showDialog && (
        <ConfirmationDialog onConfirm={handleDelete} onCancel={() => setShowDialog(false)} />
      )}
    </div>
  );
}
